@js:// 获取源代码中的Token拼接到搜索地址
var html = java.ajax(source.key);
var token = html.match(/name="_token" value="(.+?)"/);  
token = token ? token[1] : null;

var body = `_token=${token}&keyword=${key}&action=login`;
var option = { 
  "charset": "utf-8",
  "method": "POST",
  "body": body
};
source.key + "/search," + JSON.stringify(option);

ruleSearch.bookList:
$.data[*]
<js>
(() => {
	list = Array.from(result).filter(item => item.type == "book")
	return list
})()

bookList = list.map(x => `https://api.wan123x.com/read/getBookDetail?book_id=${x.id}`)

d = java.ajaxAll(bookList).map(x => x.body());

$=(b,c)=>java.getString(b,c);

Array.from(list,(a,i)=>{
	list={
		name:$("name",a),
		author:$("$..author_name",d[i]),
		kind:$("$..category1&&$..category2&&$..role&&$..ability",d[i]),
		words:$("$..words",d[i]),
		lastc:$("",d[i]),
		intro:"&nbsp;&nbsp;" + $("$..intro",d[i]),
		cover:$("$..cover_url",d[i]),
		link:`https://api.wan123x.com/read/getCatalog?book_id=${$("$..book_id",d[i])}&catalog_order=asc`
		};
		return list
	});
</js>

